-- Book Store schema: customer module, version 1.
--
-- Each business module owns its tables and migrations (ADR-0002, ADR-0018); it refers to no other module's tables.
--
-- Written for PostgreSQL 17 (ADR-0008); the fast tests run the same file on H2 in PostgreSQL mode:
--   * ids are BIGINT GENERATED BY DEFAULT AS IDENTITY,
--   * times are TIMESTAMP(6) in UTC and are set by the application, never by the database,
--   * no reserved words as column names (for example `year`, `value`, `comment`),
--   * the allowed values of a code column live in a reference table behind a foreign key, never in a
--     CHECK (... IN ...) list: H2 2.4 evaluates those with the session that created the table.
-- (2026-11-17, phase 4.6: rewritten from the MySQL dialect; no environment had applied version 1.)
-- Tables that are updated concurrently carry a `version` column for optimistic locking.

-- ---------------------------------------------------------------- customers

-- Reference table: the roles a user can have (customer.domain.Role).
CREATE TABLE roles (
    code VARCHAR(20) PRIMARY KEY
);

INSERT INTO roles (code) VALUES ('CUSTOMER'), ('ADMIN');

CREATE TABLE users (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version       INT          NOT NULL DEFAULT 0,
    email         VARCHAR(254) NOT NULL,
    first_name    VARCHAR(100) NOT NULL,
    last_name     VARCHAR(100) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    role          VARCHAR(20)  NOT NULL,
    active        BOOLEAN      NOT NULL DEFAULT TRUE,
    registered_at TIMESTAMP(6) NOT NULL,
    CONSTRAINT uq_users_email UNIQUE (email),
    CONSTRAINT fk_users_role FOREIGN KEY (role) REFERENCES roles (code)
);

CREATE TABLE addresses (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version      INT          NOT NULL DEFAULT 0,
    user_id      BIGINT       NOT NULL,
    sort_order   INT          NOT NULL,
    is_default   BOOLEAN      NOT NULL DEFAULT FALSE,
    label        VARCHAR(50)  NOT NULL,
    recipient    VARCHAR(200) NOT NULL,
    phone        VARCHAR(20)  NOT NULL,
    address_line VARCHAR(300) NOT NULL,
    district     VARCHAR(100) NOT NULL,
    city         VARCHAR(100) NOT NULL,
    postal_code  CHAR(5)      NOT NULL,
    CONSTRAINT fk_addresses_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX idx_addresses_user ON addresses (user_id);
